def compute(vars):
    start_value = vars["v1"]
    end_value = vars["v2"]
    if start_value == 0:
        return None
    change_ratio = (end_value - start_value) / start_value
    percentage_return = change_ratio * 100
    return {
        "value": percentage_return,
        "trace": {
            "start_value": start_value,
            "end_value": end_value,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
